module.exports = function(RED) {
    const sessionManager = require("../../runtime/session-manager").getInstance(RED);

    function AskQuestionNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', async function(msg) {
            const sessionId = msg.sessionId;
            if (!sessionId) return node.error("No sessionId found");

            // Store question context
            await sessionManager.updateSession(sessionId, {
                currentQuestion: config.name || node.id,
                questionText: config.ttsText
            });

            msg._ttsText = config.ttsText;
            msg._allowedResponses = config.allowedResponses;

            node.send(msg);
        });
    }

    RED.nodes.registerType("ask-question", AskQuestionNode);
};